window.B1 = [{"n": 1, "title": "Back to School", "sub": "Present simple vs. present continuous · school life", "setting": "It’s the first day of the new school year. Sara meets Diego at the school gate. Use the words in the box. Words: usually, taking, timetable, have, doing, break, know.", "lines": [{"who": "Sara", "parts": ["Diego! Hi! Why are you walking? You ", {"num": "1"}, {"gap": "u…"}, " take the bus."]}, {"who": "Diego", "parts": ["Yeah, but my mom is ", {"num": "2"}, {"gap": "t…"}, " my little brother to his new school today."]}, {"who": "Sara", "parts": ["Oh, OK! Hey, do you have the new ", {"num": "3"}, {"gap": "t…"}, "?"]}, {"who": "Diego", "parts": ["Yes, look. We ", {"num": "4"}, {"gap": "h…"}, " math first. Every day!"]}, {"who": "Sara", "parts": ["Ha! What are you ", {"num": "5"}, {"gap": "d…"}, "at ", {"num": "6"}, {"gap": "b…"}, "? Let’s go to the café."]}, {"who": "Diego", "parts": ["Sure! Oh, and do you ", {"num": "7"}, {"gap": "k…"}, " the new teacher?"]}, {"who": "Sara", "parts": ["Not yet. But everybody says he’s really cool."]}], "ansT": {"1": "usually", "2": "taking", "3": "timetable", "4": "have", "5": "doing", "6": "break", "7": "know"}, "after": "Listen again and check. Then act it out with a partner. Change the subjects and the times!", "pairs": ["💬 At the bus stop — Tell a friend about your usual morning. Then say what is different today.", "💬 Video call — Your cousin calls. Say what you’re doing right now.", "💬 New student — Explain your school timetable to a new student."], "sound": ["-s endings: The -s in the present simple has three sounds:", "/s/ walks, takes · /z/ plays, goes · /ɪz/ watches, finishes", "Say them: She watches · he plays · it takes", "In the continuous, link the words: What are you doing? → “whatcha doing?”"], "rtitle": "My First Week in 3rd Grade", "rsub": "Mateo, 14, posts a vlog every Friday", "paras": ["Hi, guys! It’s Friday and I’m sitting in the school garden. This year is different.", "I usually get up at 6:30, but this week I’m getting up at 6:00 because I’m going to school with my sister. She’s in 1st grade now. We have a new timetable: computer science on Mondays and Wednesdays — my favorite! — and history every day.", "Our new teacher, Mr. Ruiz, is really funny. He doesn’t give homework on Fridays!", "Right now, Leo and Diego are playing soccer and Sara is reading under a tree. My goal for this year? To make a short film with my friends."], "pull": "This year is different.", "atitle": "Read and answer.", "qa": ["1. Why is Mateo getting up early this week?", "2. What is his favorite subject?", "3. What is Sara doing right now?"], "qb": ["4. Mateo usually gets up at 6:00. ____", "5. His sister is in 1st grade. ____", "6. They have history every day. ____", "7. Mr. Ruiz gives homework on Fridays. ____"], "ansR": {"1": "Because he’s going to school with his sister.", "2": "Computer science", "3": "She’s reading under a tree.", "4": "F", "5": "T", "6": "T", "7": "F"}, "write": {"model_title": "Read Valeria’s post on the school blog.", "meta": "Liceo Colón · Student Blog · Valeria", "model": "This year I’m in 3rd grade! I usually take the bus, but this week I’m walking with Camila. We have art on Thursdays — I love it! Our music teacher is new. Right now we’re practicing for a concert. My goal: to sing a solo!", "useful": [["Start", "This year I’m in… grade!"], ["Routine", "I usually… / We have … on…"], ["Different", "But this week I’m…"], ["Now", "Right now we’re…"], ["Goal", "My goal for this year is to…"]], "task_title": "Write a post about your first week of school", "task": "Write 50–70 words. Include:", "cells": ["1 · Routine: What do you usually do? Subjects, days, times", "2 · This week ⏳: What is different? What are you doing now?", "3 · Goal: My goal for this year is to…"]}}, {"n": 2, "title": "Where Were You?", "sub": "was / were · there was / there were · past time words", "setting": "It’s Monday. Leo is asking Camila about the weekend. Use the words in the box. Words: were, was, wasn’t, there, ago, last, crowded.", "lines": [{"who": "Leo", "parts": ["Hey, Camila! Where ", {"num": "1"}, {"gap": "w…"}, " you on Saturday? I called you!"]}, {"who": "Camila", "parts": ["Sorry! I ", {"num": "2"}, {"gap": "w…"}, " at the Bad Bunny concert in Santo Domingo!"]}, {"who": "Leo", "parts": ["No way! Was it good?"]}, {"who": "Camila", "parts": ["It was amazing! ", {"num": "3"}, {"gap": "T…"}, "were 40,000 people. It was really ", {"num": "4"}, {"gap": "c…"}, "."]}, {"who": "Leo", "parts": ["Wow. Were your parents with you?"]}, {"who": "Camila", "parts": ["My mom was there, but my dad ", {"num": "5"}, {"gap": "w…"}, ". He was at work."]}, {"who": "Leo", "parts": ["Lucky you! My last concert was two years ", {"num": "6"}, {"gap": "a…"}, ". And where were you ", {"num": "7"}, {"gap": "l…"}, " night?"]}, {"who": "Camila", "parts": ["In bed! I was soooo tired."]}], "ansT": {"1": "were", "2": "was", "3": "There", "4": "crowded", "5": "wasn’t", "6": "ago", "7": "last"}, "after": "Listen again and check. Then act it out. Change the place: a game, a party, the beach…", "pairs": ["💬 After a concert — Tell a friend where you were and what it was like.", "💬 Monday morning — Ask a classmate about the weekend. Who was there?", "💬 Missed call — Your mom called 5 times! Explain where you were."], "sound": ["Weak forms: In fast English, was and were are short and weak:", "I was /wəz/ at home. · We were /wər/ late.", "But at the end of a short answer they’re strong: Yes, I was /wɑz/!", "Say it: Where were you? → “where-wer-yuh?”"], "rtitle": "The Night the Lights Went Out", "rsub": "Sara, 14, remembers a blackout", "paras": ["Last August there was a big blackout in Santiago. It was 8 o’clock at night and I was at home with my family. There wasn’t any electricity, so there was no TV, no Wi-Fi and no air conditioning. At first, I was really bored.", "My little brother was scared because it was very dark. Then my grandpa had an idea: stories! There were candles on the table and we were all in the living room. His stories about the old days in Moca were so funny!", "The blackout was four hours long, but it wasn’t a bad night. It was one of my favorite nights of the year."], "pull": "It wasn’t a bad night.", "atitle": "Read and answer.", "qa": ["1. Why was there no TV?", "2. Where were the candles?", "3. What were Grandpa’s stories about?"], "qb": ["4. The blackout was in the morning. ____", "5. Sara was at home. ____", "6. Her brother was scared. ____", "7. The blackout was two hours long. ____"], "ansR": {"1": "Because there wasn’t any electricity.", "2": "On the table.", "3": "The old days in Moca.", "4": "F", "5": "T", "6": "T", "7": "F"}, "write": {"model_title": "Read Diego’s post.", "meta": "Diego · Memories · Diego", "model": "Two years ago I was at the Estadio Cibao for my first baseball game. I was with my dad and my uncle. There were thousands of people and the noise was incredible! The Águilas were the winners. I wasn’t tired at all. It was the best day ever!", "useful": [["When", "Two years ago… / Last summer…"], ["Where", "I was at / in…"], ["Who", "I was with…"], ["What", "There was… / There were…"], ["Feelings", "It was amazing! / I was so…"]], "task_title": "Write about a special day in the past", "task": "Write 50–70 words. Include:", "cells": ["1 · When & where: Two years ago I was at…", "2 · Who & what: I was with… There was / were…", "3 · Feelings: It was… I was…"]}}, {"n": 3, "title": "Last Weekend", "sub": "Past simple: regular verbs · -ed pronunciation · weekend activities", "setting": "Monday morning. Diego and Valeria talk about the weekend. Use the words in the box. Words: played, stayed, watched, helped, cooked, tried, relaxed.", "lines": [{"who": "Diego", "parts": ["Hey Valeria! How was your weekend?"]}, {"who": "Valeria", "parts": ["Busy! On Saturday I ", {"num": "1"}, {"gap": "h…"}, " my mom at her bakery all morning."]}, {"who": "Diego", "parts": ["Cool! Did you make anything?"]}, {"who": "Valeria", "parts": ["Yes! I ", {"num": "2"}, {"gap": "t…"}, " to make a chocolate cake. It was a disaster! What about you?"]}, {"who": "Diego", "parts": ["I ", {"num": "3"}, {"gap": "p…"}, "in a basketball game, and we won! Then I ", {"num": "4"}, {"gap": "s…"}, "up late and ", {"num": "5"}, {"gap": "w…"}, " a movie."]}, {"who": "Valeria", "parts": ["Nice! And on Sunday?"]}, {"who": "Diego", "parts": ["I ", {"num": "6"}, {"gap": "s…"}, "at home. I just ", {"num": "7"}, {"gap": "r…"}, " and listened to music."]}, {"who": "Valeria", "parts": ["Lucky you!"]}], "ansT": {"1": "helped", "2": "tried", "3": "played", "4": "stayed", "5": "watched", "6": "stayed", "7": "relaxed"}, "after": "Listen again and check. Then talk about YOUR weekend with a partner.", "pairs": ["💬 Sports chat — Tell a friend about a game you played. Did you win?", "💬 Video call — Your cousin in New York asks about your weekend.", "💬 Busy Saturday — Tell your teacher all the jobs you did at home."], "sound": ["-ed endings: Three sounds for -ed:", "/t/ helped, cooked, relaxed · /d/ played, stayed, tried · /ɪd/ wanted, needed", "Clap the syllables: play-ed played (1 clap!) · want-ed (2 claps)"], "rtitle": "Sunday Night Chat", "rsub": "The squad talks about their weekend", "paras": ["Leo: Guys, what a weekend! We played against Liceo Moca and we won 7–3!", "Sara: Congrats!! I stayed at home and studied for the history test. Boring…", "Camila: I visited my grandma in Jarabacoa. We walked to the waterfall and I painted a picture of it.", "Mateo: Nice! I filmed a skateboard video with my cousins. I edited it until 2 am.", "Diego: I cleaned my room… finally. My mom cried.", "Valeria: Hahaha! I practiced for the concert. My fingers hurt!", "Sara: OK, OK, I want a weekend like Camila’s next time!"], "pull": "I want a weekend like Camila’s!", "atitle": "Read and answer.", "qa": ["1. Where does Camila’s grandma live?", "2. Who did Mateo film the video with?", "3. Why did Diego’s mom cry? (Guess!)"], "qb": ["4. Leo’s team lost the game. ____", "5. Sara studied for a test. ____", "6. Camila painted a waterfall. ____", "7. Mateo stopped editing at 10 pm. ____"], "ansR": {"1": "In Jarabacoa.", "2": "With his cousins.", "3": "Because he finally cleaned his room — she was happy! 😂", "4": "F", "5": "T", "6": "T", "7": "F"}, "write": {"model_title": "Read Camila’s post.", "meta": "Camila · Weekend vibes · Camila", "model": "Last weekend was super relaxing! On Saturday morning I visited my grandma in Jarabacoa. We cooked sancocho together and I helped in her garden. In the afternoon we walked to a waterfall and I painted it. On Sunday I stayed in bed and watched a series. Perfect!", "useful": [["Start", "Last weekend was… (busy / relaxing / fun)"], ["Saturday", "On Saturday morning I…"], ["Then", "In the afternoon… / After that…"], ["Sunday", "On Sunday I…"], ["Opinion", "It was perfect! / I loved it!"]], "task_title": "Write a post about your weekend", "task": "Write 50–70 words. Include:", "cells": ["1 · Saturday: What did you do in the morning / afternoon?", "2 · Sunday: Where did you stay? Who did you visit?", "3 · Opinion: It was… I loved / didn’t like…"]}}, {"n": 4, "title": "Travel Stories", "sub": "Past simple: irregular verbs · travel and holidays", "setting": "Camila is back from a trip to Samaná. She tells Leo about it. Use the words in the box. Words: went, took, saw, had, bought, First, After that.", "lines": [{"who": "Leo", "parts": ["Welcome back! So, how was Samaná?"]}, {"who": "Camila", "parts": ["Incredible! We ", {"num": "1"}, {"gap": "w…"}, " on a whale-watching tour."]}, {"who": "Leo", "parts": ["No way! Tell me everything."]}, {"who": "Camila", "parts": [{"num": "2"}, {"gap": "F…"}, ", we ", {"num": "3"}, {"gap": "t…"}, " a boat at 8 am. The sea was really rough!"]}, {"who": "Leo", "parts": ["Oh no! Were you sick?"]}, {"who": "Camila", "parts": ["A little. But then we ", {"num": "4"}, {"gap": "s…"}, " three humpback whales! One jumped out of the water!"]}, {"who": "Leo", "parts": ["Wow! What did you do ", {"num": "5"}, {"gap": "a…"}, "?"]}, {"who": "Camila", "parts": ["We ", {"num": "6"}, {"gap": "h…"}, "lunch at Las Galeras and I ", {"num": "7"}, {"gap": "b…"}, " you a souvenir. Here!"]}, {"who": "Leo", "parts": ["A whale keychain! Thanks!"]}], "ansT": {"1": "went", "2": "First", "3": "took", "4": "saw", "5": "after that", "6": "had", "7": "bought"}, "after": "Listen again and check. Then tell a partner about YOUR best trip.", "pairs": ["💬 Beach trip — Tell a friend about a day at the beach. What did you eat?", "💬 Pico Duarte — You climbed a mountain! Tell the story in order.", "💬 First flight — Describe your first time on a plane (real or imaginary)."], "sound": ["Irregular verb sounds: Group the verbs by sound — it helps you remember:", "/ɔ/ bought, thought, caught, taught", "/ʊ/ took, looked, stood · /eɪ/ ate, came, made, gave", "Careful: ate sounds like eight 8⃣"], "rtitle": "Three Days on Pico Duarte", "rsub": "Leo, 15, climbed the highest mountain in the Caribbean", "paras": ["Last March I climbed Pico Duarte with my dad and my uncle. It’s 3,098 meters high — the highest mountain in the Caribbean! First, we drove to La Ciénaga and met our guide, Don Ramón.", "Then we walked for nine hours. My legs were destroyed! We slept at a cabin called La Compartición.", "It was freezing — only 2 degrees! The next day, we got up at 3 am and walked in the dark. At 6:15 we got to the top and saw the sunrise above the clouds.", "I took 200 photos. Finally, we came down and ate a huge plate of rice and beans. Best trip ever!"], "pull": "We saw the sunrise above the clouds.", "atitle": "Read and answer.", "qa": ["1. How high is Pico Duarte?", "2. Who was Don Ramón?", "3. What did they eat at the end?"], "qb": ["4. Leo climbed the mountain with his friends. ____", "5. They walked for nine hours on the first day. ____", "6. It was very hot at the cabin. ____", "7. They got to the top at 6:15. ____"], "ansR": {"1": "3,098 meters.", "2": "Their guide.", "3": "A huge plate of rice and beans.", "4": "F", "5": "T", "6": "F", "7": "T"}, "write": {"model_title": "Read Valeria’s postcard.", "meta": "Postcard · Las Terrenas · Valeria", "model": "Hi Sara! Greetings from Las Terrenas! We got here on Friday by bus. First, we went to Playa Bonita and I swam for hours. Then we ate coconut fish — so good! Yesterday I saw the El Limón waterfall. I bought you a bracelet! See you on Monday. Love, Valeria", "useful": [["Start", "Hi…! Greetings from…!"], ["Arrival", "We got here on… by…"], ["Story", "First… Then… After that…"], ["Gift", "I bought you…"], ["End", "See you soon! Love,… / Bye!"]], "task_title": "Write a postcard from a real or dream trip", "task": "Write 50–70 words. Include:", "cells": ["1 · Arrival: Where are you? How did you get there?", "2 · Story: What did you do? First… Then…", "3 · Goodbye: A gift, see you soon, your name"]}}, {"n": 5, "title": "Did You…?", "sub": "Past simple: questions and negatives · short answers · ago", "setting": "Diego can’t find his house keys. Sara asks him questions. Use the words in the box. Words: did, didn’t, go, take, Where, ago, look.", "lines": [{"who": "Diego", "parts": ["Oh no… My keys! I can’t find them anywhere!"]}, {"who": "Sara", "parts": ["Calm down, detective time. When ", {"num": "1"}, {"gap": "d…"}, " you last see them?"]}, {"who": "Diego", "parts": ["About two hours ", {"num": "2"}, {"gap": "a…"}, ", at the café."]}, {"who": "Sara", "parts": ["OK. Did you ", {"num": "3"}, {"gap": "g…"}, " anywhere after the café?"]}, {"who": "Diego", "parts": ["Yes, I went to the library. But I ", {"num": "4"}, {"gap": "d…"}, " open my backpack there."]}, {"who": "Sara", "parts": ["Hmm. ", {"num": "5"}, {"gap": "W…"}, " did you sit at the café?"]}, {"who": "Diego", "parts": ["Next to the window. Did I ", {"num": "6"}, {"gap": "t…"}, " them out of my pocket? I don’t remember!"]}, {"who": "Sara", "parts": ["Let’s go back and ", {"num": "7"}, {"gap": "l…"}, ". … Look! On the chair!"]}, {"who": "Diego", "parts": ["You’re a genius!"]}], "ansT": {"1": "did", "2": "ago", "3": "go", "4": "didn’t", "5": "Where", "6": "take", "7": "look"}, "after": "Listen again and check. Then act it out with something else: a phone, a wallet, a cap…", "pairs": ["💬 Lost item — Your friend lost something. Ask 5 questions to help.", "💬 Movie night — Ask a friend about a movie they saw. Did they like it?", "💬 Detective — Interview a “witness”: Where were you? What did you see?"], "sound": ["Did you…?: In fast English, Did you sounds like “didja” /dɪdʒə/:", "Did you see it? → “didja see it?” · What did you do? → “whadidja do?”", "Yes/No questions go up ↗ · Wh- questions go down ↘"], "rtitle": "10 Questions for a Young Chef", "rsub": "Sara interviews Andrea, 16, winner of a TV cooking show", "paras": ["When did you start cooking? When I was eight. My grandma taught me to make habichuelas con dulce.", "Did you study cooking? No, I didn’t. I learned from YouTube videos and from my family!", "How did you feel on the show? Super nervous. In the first round I didn’t finish my dessert in time.", "What did you cook in the final? A mangú with a modern twist and a passion fruit mousse.", "Did your family watch? Yes! My whole neighborhood watched it on a big screen.", "What did you do with the prize? I bought a new oven and I saved the rest for chef school."], "pull": "I learned from YouTube and from my family!", "atitle": "Read and answer.", "qa": ["1. How old was Andrea when she started cooking?", "2. What did she cook in the final?", "3. Where did her neighborhood watch the show?"], "qb": ["4. Andrea’s grandma taught her to cook. ____", "5. She studied at a cooking school. ____", "6. She finished her dessert in the first round. ____", "7. She bought a new oven. ____"], "ansR": {"1": "Eight.", "2": "Mangú with a modern twist and a passion fruit mousse.", "3": "On a big screen.", "4": "T", "5": "F", "6": "F", "7": "T"}, "write": {"model_title": "Read Mateo’s questions for a YouTuber.", "meta": "Mateo · Interview plan · Mateo", "model": "My star: a famous Dominican YouTuber 1. When did you post your first video? 2. What did you use — a camera or a phone? 3. Did you have many followers at the start? 4. Who helped you? 5. Were you nervous in your first video?", "useful": [["Start", "When did you start…?"], ["Past", "Where did you grow up?"], ["Feelings", "Were you nervous / happy…?"], ["Yes / No", "Did you ever think…?"], ["Fun", "What did you buy with…?"]], "task_title": "Write interview questions for a famous person", "task": "Write 5–6 questions + answers. Include:", "cells": ["1 · Choose: A singer, athlete, gamer, actor…", "2 · Questions: When / where / what / why did you…?", "3 · Answers: Imagine their answers in the past"]}}, {"n": 6, "title": "Famous Firsts", "sub": "Past simple in biographies · when · dates and years · sequencing", "setting": "Sara and Mateo are preparing a presentation about a famous person. Use the words in the box. Words: born, grew, when, became, won, first, in.", "lines": [{"who": "Sara", "parts": ["OK, our person is Marileidy Paulino. Where was she ", {"num": "1"}, {"gap": "b…"}, "?"]}, {"who": "Mateo", "parts": ["In Don Gregorio, Nizao. She ", {"num": "2"}, {"gap": "g…"}, " up there with her family."]}, {"who": "Sara", "parts": ["And did she always run?"]}, {"who": "Mateo", "parts": ["No! She played softball ", {"num": "3"}, {"gap": "w…"}, " she was a girl. She started athletics later."]}, {"who": "Sara", "parts": ["Really? Interesting! And then she ", {"num": "4"}, {"gap": "b…"}, " a star. ⭐"]}, {"who": "Mateo", "parts": ["Yes! She ", {"num": "5"}, {"gap": "w…"}, " the gold medal in the 400 meters at the Paris Olympics."]}, {"who": "Sara", "parts": ["When was that? ", {"num": "6"}, {"gap": "I…"}, " 2024?"]}, {"who": "Mateo", "parts": ["Yes. She was the ", {"num": "7"}, {"gap": "f…"}, " Dominican woman to win Olympic gold!"]}, {"who": "Sara", "parts": ["Amazing. Let’s make the slides!"]}], "ansT": {"1": "born", "2": "grew", "3": "when", "4": "became", "5": "won", "6": "In", "7": "first"}, "after": "Listen again and check. Then present another famous person in the same way.", "pairs": ["💬 Sports star — Tell the life of a famous athlete in 5 sentences.", "💬 Family hero — Tell a partner about the life of a grandparent.", "💬 Inventor — Present an inventor. What did he / she invent? When?"], "sound": ["Years: Say the years in two parts:", "19 | 98 nineteen ninety-eight · 20 | 24 twenty twenty-four", "But: 2008 two thousand eight", "Stress the numbers: thirTEEN (13) vs. THIRty (30)!"], "rtitle": "Ellen Ochoa: From Music to Space", "rsub": "The first Latina astronaut", "paras": ["Ellen Ochoa was born in Los Angeles, California, on May 10th, 1958. Her family had Mexican roots. When she was a teenager, she loved music and she played the flute. At university she studied physics, and then she became an engineer.", "She invented systems that help computers “see” images. In 1990, NASA chose her as an astronaut. Three years later, in 1993, she went to space on the shuttle Discovery — she was the first Latina woman in space! She flew four times and spent almost 1,000 hours in space.", "She even took her flute and played it in orbit! Later, she became the director of the Johnson Space Center."], "pull": "She took her flute and played it in orbit!", "atitle": "Read and answer.", "qa": ["1. What did she study at university?", "2. Why is 1993 important?", "3. What job did she have later?"], "qb": ["4. Ellen Ochoa was born in Mexico. ____", "5. She played the flute as a teenager. ____", "6. She went to space for the first time in 1990. ____", "7. She flew four times. ____"], "ansR": {"1": "Physics.", "2": "She went to space — the first Latina woman in space.", "3": "Director of the Johnson Space Center.", "4": "F", "5": "T", "6": "F", "7": "T"}, "write": {"model_title": "Read Camila’s biography.", "meta": "Camila · My hero · Camila", "model": "Julia Álvarez was born in New York in 1950, but she grew up in the Dominican Republic. When she was ten, her family moved to the USA. Then she fell in love with books. She became a famous writer. I admire her because she never gave up!", "useful": [["Birth", "… was born in (place) in (year)."], ["Childhood", "He / She grew up in… When he / she was…"], ["Career", "Then he / she became… / won…"], ["Big moment", "In (year), he / she…"], ["Why", "I admire him / her because…"]], "task_title": "Write a biography of a person you admire", "task": "Write 60–80 words. Include:", "cells": ["1 · Early life: Born where / when? Grew up where?", "2 · Career: What did he / she do? Big moments with years", "3 · Why: Why do you admire this person?"]}}, {"n": 7, "title": "Bigger, Better, Faster", "sub": "Comparative adjectives · than · tech and gadgets", "setting": "Sara wants a new phone. She’s at a store with Leo. Use the words in the box. Words: cheaper, better, bigger, than, more, lighter, worse.", "lines": [{"who": "Sara", "parts": ["OK, I need help. The Galaxy or the Moto?"]}, {"who": "Leo", "parts": ["Well, the Moto is ", {"num": "1"}, {"gap": "c…"}, ". It’s only 11,000 pesos."]}, {"who": "Sara", "parts": ["Yes, but the Galaxy camera is ", {"num": "2"}, {"gap": "b…"}, ". I take a lot of photos."]}, {"who": "Leo", "parts": ["True. And the Galaxy screen is ", {"num": "3"}, {"gap": "b…"}, " — good for series!"]}, {"who": "Sara", "parts": ["But it’s heavier ", {"num": "4"}, {"gap": "t…"}, " the Moto."]}, {"who": "Leo", "parts": ["Hmm, the Moto is ", {"num": "5"}, {"gap": "l…"}, ", but the battery is ", {"num": "6"}, {"gap": "w…"}, ". Only one day."]}, {"who": "Sara", "parts": ["Ugh! The Galaxy is ", {"num": "7"}, {"gap": "m…"}, " expensive, but I think it’s the one."]}, {"who": "Leo", "parts": ["Good choice. Now, let’s get ice cream. That’s cheaper!"]}], "ansT": {"1": "cheaper", "2": "better", "3": "bigger", "4": "than", "5": "lighter", "6": "worse", "7": "more"}, "after": "Listen again and check. Then compare two products in a role-play: sneakers, bikes, headphones…", "pairs": ["💬 At the store — Help a friend choose between two gadgets.", "💬 Food fight — Compare two places to eat. Which is better?", "💬 City vs. town — Compare Santiago and Santo Domingo (or two places you know)."], "sound": ["Weak “than”: than is weak and short: /ðən/ — “thn”.", "bigger than → “bigger-thn” · better than mine → “better-thn-mine”", "Stress the adjective: BIGger than · more exPENsive than"], "rtitle": "Earbuds Battle: Cheap vs. Pro", "rsub": "Mateo tests two pairs of earbuds", "paras": ["This week I tested two pairs of earbuds: the SoundGo (RD$1,500) and the AirMax Pro (RD$9,000). First, the design. The AirMax are smaller and lighter, and they look more modern. The SoundGo are bigger, but more comfortable.", "The sound? The AirMax are clearly better — the bass is deeper and the voices are clearer. But here’s the surprise: the SoundGo battery is longer! Seven hours, and the AirMax only five.", "So which is better for you? If you want the best sound and you have the money, buy the AirMax. But for school, the gym and the bus, the SoundGo are cheaper and almost as good. My choice?", "The SoundGo — I lose earbuds every month!"], "pull": "Cheaper and almost as good!", "atitle": "Read and answer.", "qa": ["1. How much more expensive are the AirMax?", "2. Which have better sound?", "3. Why does Mateo choose the cheaper ones?"], "qb": ["4. The AirMax are bigger than the SoundGo. ____", "5. The SoundGo are more comfortable for Mateo. ____", "6. The AirMax battery is longer. ____", "7. Mateo chooses the SoundGo. ____"], "ansR": {"1": "RD$7,500 more.", "2": "The AirMax Pro.", "3": "Because he loses earbuds every month.", "4": "F", "5": "T", "6": "F", "7": "T"}, "write": {"model_title": "Read Camila’s comparison.", "meta": "Camila · Choices · Camila", "model": "Skates or a bike? Skates are cheaper than bikes and they’re lighter, so I can take them everywhere. But a bike is faster and safer on the street. Skates are more fun in the park, but a bike is more useful for going to school. My choice? The bike! It’s better for every day.", "useful": [["Question", "X or Y? 🤔"], ["Good points", "X is cheaper / lighter than…"], ["But", "But Y is faster / more useful…"], ["Both", "X is more fun, but Y is…"], ["Choice", "My choice? … It’s better for…"]], "task_title": "Compare two things and choose one", "task": "Write 50–70 words. Include:", "cells": ["1 · Question: X or Y?", "2 · Compare: 3–4 comparatives with than", "3 · Choice: My choice is… because…"]}}, {"n": 8, "title": "The Best in the World", "sub": "Superlative adjectives · records · places and nature", "setting": "The squad is at a quiz night at school. Ms. Peña asks the questions. Use the words in the box. Words: highest, biggest, longest, best, most, in, of.", "lines": [{"who": "Ms. Peña", "parts": ["Question 1: What is the ", {"num": "1"}, {"gap": "h…"}, "mountain ", {"num": "2"}, {"gap": "i…"}, " the Caribbean?"]}, {"who": "Leo", "parts": ["Easy! Pico Duarte. I climbed it!"]}, {"who": "Ms. Peña", "parts": ["Correct! Question 2: What is the ", {"num": "3"}, {"gap": "b…"}, " animal in the world?"]}, {"who": "Sara", "parts": ["The blue whale!"]}, {"who": "Ms. Peña", "parts": ["Yes! Question 3: What is the ", {"num": "4"}, {"gap": "l…"}, " river in the DR?"]}, {"who": "Diego", "parts": ["Hmm… the Yaque del Norte!"]}, {"who": "Ms. Peña", "parts": ["Very good. Last question: Who is the ", {"num": "5"}, {"gap": "m…"}, "famous Dominican baseball player ", {"num": "6"}, {"gap": "o…"}, " all time?"]}, {"who": "Mateo", "parts": ["That’s difficult! Pedro Martínez? David Ortiz?"]}, {"who": "Ms. Peña", "parts": ["Both are great answers! You’re the ", {"num": "7"}, {"gap": "b…"}, " team tonight!"]}], "ansT": {"1": "highest", "2": "in", "3": "biggest", "4": "longest", "5": "most", "6": "of", "7": "best"}, "after": "Listen again and check. Then make your own quiz with 5 questions for the class!", "pairs": ["💬 Travel agent — Recommend the best place in your country to a tourist.", "💬 Best of the year — Talk about the best movie, song and game of the year.", "💬 Class awards — Give “awards”: the funniest, the kindest, the fastest…"], "sound": ["-est: -est is a short, weak syllable: /ɪst/", "tallest, biggest, longest → “TALL-ist”, “BIG-ist”", "In the most, stress the adjective: the most BEAUtiful · the most FAmous"], "rtitle": "Record Breakers of the Caribbean", "rsub": "Five amazing facts about the Dominican Republic", "paras": ["Did you know that the Dominican Republic has some of the most amazing places in the Caribbean? Pico Duarte (3,098 m) is the highest mountain in the Caribbean. But the DR also has the lowest point: Lake Enriquillo is about 40 meters below sea level, and it’s the biggest lake in the Caribbean.", "It’s also one of the hottest places in the country, and you can see wild crocodiles and iguanas there! Santo Domingo is the oldest European city in the Americas — its cathedral, from the 1500s, is the oldest in the Americas too. And for nature lovers, the humpback whales in Samaná are some of the biggest visitors: they can be 16 meters long!"], "pull": "The highest and the lowest — in one country!", "atitle": "Read and answer.", "qa": ["1. What is the biggest lake in the Caribbean?", "2. What is special about Santo Domingo?", "3. How long can the humpback whales be?"], "qb": ["4. Pico Duarte is the highest mountain in the Caribbean. ____", "5. Lake Enriquillo is above sea level. ____", "6. There are crocodiles at Lake Enriquillo. ____", "7. The whales in Samaná can be 60 meters long. ____"], "ansR": {"1": "Lake Enriquillo.", "2": "It’s the oldest European city in the Americas.", "3": "16 meters.", "4": "T", "5": "F", "6": "T", "7": "F"}, "write": {"model_title": "Read Leo’s Top 3.", "meta": "Leo · Top 3 Beaches · Leo", "model": "My Top 3 beaches in the DR Playa Rincón — the most beautiful beach I know. The water is the clearest! Cabarete — the best place for kitesurfing. Boca Chica — not the prettiest, but it’s the closest.", "useful": [["Title", "My Top 3… in…"], ["Number 1", "the most beautiful / the best…"], ["Reason", "It’s the… because…"], ["Contrast", "not the…, but…"], ["End", "What’s your number 1? 🤔"]], "task_title": "Write your own Top 3", "task": "Write 50–70 words. Include:", "cells": ["1 · Topic: beaches, foods, songs, games, places…", "2 · 1–2–3: Each with a superlative and a reason", "3 · Question: Ask your readers for their number 1"]}}, {"n": 9, "title": "How Much? How Many?", "sub": "Countable / uncountable · much, many, a lot of, a few, a little · food", "setting": "Diego and Valeria are making breakfast for the squad. Use the words in the box. Words: How many, How much, a few, a little, much, any, bag.", "lines": [{"who": "Diego", "parts": ["OK, chef. Mangú for ten people. ", {"num": "1"}, {"gap": "H…"}, " plantains do we need?"]}, {"who": "Valeria", "parts": ["About fifteen. Are there ", {"num": "2"}, {"gap": "a…"}, " in the kitchen?"]}, {"who": "Diego", "parts": ["Only ", {"num": "3"}, {"gap": "a…"}, ". Five or six."]}, {"who": "Valeria", "parts": ["Then we need to buy more. And onions?"]}, {"who": "Diego", "parts": ["We have a lot of onions. ", {"num": "4"}, {"gap": "H…"}, " oil do we need?"]}, {"who": "Valeria", "parts": ["Just ", {"num": "5"}, {"gap": "a…"}, ". And we need a ", {"num": "6"}, {"gap": "b…"}, " of salami and some cheese."]}, {"who": "Diego", "parts": ["Hmm, there isn’t ", {"num": "7"}, {"gap": "m…"}, " money in my wallet…"]}, {"who": "Valeria", "parts": ["Don’t worry. Everybody brings 100 pesos!"]}], "ansT": {"1": "How many", "2": "any", "3": "a few", "4": "How much", "5": "a little", "6": "bag", "7": "much"}, "after": "Listen again and check. Then plan a meal for your class with a partner.", "pairs": ["💬 At the colmado — Buy ingredients for a meal. Ask how much they are.", "💬 Recipe — Explain your favorite recipe to a partner.", "💬 Healthy? — Ask about a partner’s eating habits: How much…? How many…?"], "sound": ["Linking: Link the words — it sounds more natural:", "a lot of → “a-lotta” · a bag of rice → “a-bagga rice”", "How much is it? → “how-muchiz-it?”", "of is weak: /əv/ or just /ə/"], "rtitle": "Grandma’s Habichuelas con Dulce", "rsub": "Camila shares a family recipe for Easter", "paras": ["This is my grandma’s recipe, and it’s the best! It’s a sweet cream of beans that Dominicans eat at Easter. You need: a pound of red beans, two cans of coconut milk, a can of evaporated milk, a cup of sugar, a little salt, a few pieces of sweet potato, some raisins and a few cinnamon sticks.", "Grandma doesn’t use much sugar — she says the sweet potato is sweet enough. First, cook the beans for one hour. Then blend them with a little water.", "After that, add the milk, sugar, cinnamon and sweet potato and cook for 30 minutes. Serve it cold with some milk cookies on top. It takes a lot of time, but it’s worth it!"], "pull": "It takes a lot of time, but it’s worth it!", "atitle": "Read and answer.", "qa": ["1. How much sugar do you need?", "2. How long do you cook the beans first?", "3. What do you put on top?"], "qb": ["4. Dominicans eat habichuelas con dulce at Christmas. ____", "5. You need two cans of coconut milk. ____", "6. Grandma uses a lot of sugar. ____", "7. You serve it cold. ____"], "ansR": {"1": "A cup.", "2": "For one hour.", "3": "Some milk cookies.", "4": "F", "5": "T", "6": "F", "7": "T"}, "write": {"model_title": "Read Mateo’s recipe.", "meta": "Mateo · Easy Breakfast · Mateo", "model": "Quick egg sandwich (for 2) · You need: 4 pieces of bread, 2 eggs, a little butter, a few slices of tomato and some cheese. Steps: First, fry the eggs in the butter. Then toast the bread. Add the cheese and tomato. Done in 5 minutes! ⏱", "useful": [["Title", "Easy… / My favorite… (for 2)"], ["Ingredients", "You need: a bag of…, a few…, some…"], ["Steps", "First,… Then,… After that,…"], ["End", "Done in… minutes! Enjoy!"]], "task_title": "Write a recipe for a simple dish", "task": "Write 50–70 words. Include:", "cells": ["1 · Name: Dish and number of people", "2 · Ingredients: quantities: a few, a little, some, a cup of…", "3 · Steps: First… Then… Finally…"]}}, {"n": 10, "title": "Too Big, Not Big Enough", "sub": "too + adjective · (not) + adjective + enough · clothes and shopping", "setting": "Leo is at a sneaker store with Mateo. Use the words in the box. Words: try, size, too, enough, How much, exchange, cheaper.", "lines": [{"who": "Leo", "parts": ["Excuse me, can I ", {"num": "1"}, {"gap": "t…"}, " on these sneakers? The blue ones."]}, {"who": "Assistant", "parts": ["Of course. What ", {"num": "2"}, {"gap": "s…"}, " are you?"]}, {"who": "Leo", "parts": ["Ten, I think."]}, {"who": "Assistant", "parts": ["Here you are. How are they?"]}, {"who": "Leo", "parts": ["Hmm, they’re ", {"num": "3"}, {"gap": "t…"}, " tight. Do you have a ten and a half?"]}, {"who": "Assistant", "parts": ["Yes. … Here. Are they big ", {"num": "4"}, {"gap": "e…"}, "?"]}, {"who": "Leo", "parts": ["Perfect! ", {"num": "5"}, {"gap": "H…"}, " are they?"]}, {"who": "Assistant", "parts": ["They’re 5,500 pesos."]}, {"who": "Mateo", "parts": ["Whoa! The black ones are ", {"num": "6"}, {"gap": "c…"}, " — only 3,800."]}, {"who": "Leo", "parts": ["Hmm… OK, the black ones. Can I ", {"num": "7"}, {"gap": "e…"}, " them if there’s a problem?"]}, {"who": "Assistant", "parts": ["Sure, with the receipt."]}], "ansT": {"1": "try", "2": "size", "3": "too", "4": "enough", "5": "How much", "6": "cheaper", "7": "exchange"}, "after": "Listen again and check. Then role-play: you’re buying a jacket, a cap or a dress.", "pairs": ["💬 Winter trip — You need a jacket for New York. Is it warm enough?", "💬 Exchange — Return a T-shirt to a store. Explain the problem.", "💬 Party outfit — Help a friend choose clothes for a party."], "sound": ["Too / two / to: too, two and to sound the same: /tuː/!", "two shirts · too big · go to the store", "But to is often weak: “go t’the store” /tə/.", "Stress too: It’s TOO expensive!"], "rtitle": "Second-hand, First Class", "rsub": "Valeria’s blog about thrift shopping", "paras": ["Hi, fashion lovers! Last Saturday I went to a “paca” (a second-hand clothes market) in Santiago with 600 pesos. Is that enough money for a full outfit?", "YES! First I found a denim jacket for 150 pesos. It was too big, but oversized jackets are in style, so it’s perfect.", "Then I found white sneakers — they were a little dirty, but not too bad. After a wash, they look new! The only problem?", "A pair of vintage jeans. I loved them, but they were too short for me. Why do I love thrift shopping?", "It’s cheaper, it’s more original, and it’s better for the planet: the fashion industry makes a lot of waste. My tip: go early, because the best things go fast!"], "pull": "Is 600 pesos enough for a full outfit? YES!", "atitle": "Read and answer.", "qa": ["1. How much was the jacket?", "2. What was the problem with the jeans?", "3. What is her tip?"], "qb": ["4. Valeria went shopping with 600 pesos. ____", "5. The jacket was too small. ____", "6. She bought the vintage jeans. ____", "7. Thrift shopping is better for the planet. ____"], "ansR": {"1": "150 pesos.", "2": "They were too short.", "3": "Go early, because the best things go fast.", "4": "T", "5": "F", "6": "F", "7": "T"}, "write": {"model_title": "Read Diego’s review.", "meta": "⭐⭐⭐ Diego · Gaming chair · Diego", "model": "3/5 stars — I bought this gaming chair online. The design is very cool and the color is great. But it’s too big for my room, and it’s not comfortable enough for long sessions — my back hurts after two hours! The price (8,000 pesos) is too high for the quality. My advice: try it in a store first!", "useful": [["Start", "I bought this… online / at…"], ["Good", "The… is very nice / comfortable…"], ["Problem", "But it’s too… / not… enough"], ["Price", "The price is / isn’t… enough"], ["Advice", "My advice: … ⭐"]], "task_title": "Write a review of something you bought", "task": "Write 50–70 words. Include:", "cells": ["1 · Product ⭐: What, where, how many stars?", "2 · Good & bad: very…, too…, not… enough", "3 · Advice: Would you recommend it?"]}}, {"n": 11, "title": "Mine, Yours, Theirs", "sub": "Possessive pronouns · whose · lost and found · sharing", "setting": "Ms. Peña has a box of lost things after the school trip. Use the words in the box. Words: Whose, mine, yours, his, hers, ours, theirs.", "lines": [{"who": "Ms. Peña", "parts": ["OK, everybody. ", {"num": "1"}, {"gap": "W…"}, " cap is this? It was on the bus."]}, {"who": "Leo", "parts": ["It’s ", {"num": "2"}, {"gap": "m…"}, "! Thank you, Ms. Peña."]}, {"who": "Ms. Peña", "parts": ["And these sunglasses? Sara, are they ", {"num": "3"}, {"gap": "y…"}, "?"]}, {"who": "Sara", "parts": ["No, they aren’t. I think they’re Camila’s."]}, {"who": "Camila", "parts": ["Yes, they’re ", {"num": "4"}, {"gap": "m…"}, "! I looked for them everywhere."]}, {"who": "Ms. Peña", "parts": ["And this charger? Is it Diego’s?"]}, {"who": "Mateo", "parts": ["Yes, it’s ", {"num": "5"}, {"gap": "h…"}, ". He’s at the nurse’s office."]}, {"who": "Ms. Peña", "parts": ["And this big speaker?"]}, {"who": "Valeria", "parts": ["It’s ", {"num": "6"}, {"gap": "o…"}, "— the music club’s. And those balls are the soccer team’s — they’re ", {"num": "7"}, {"gap": "t…"}, "."]}], "ansT": {"1": "Whose", "2": "mine", "3": "yours", "4": "mine", "5": "his", "6": "ours", "7": "theirs"}, "after": "Listen again and check. Then play Lost and Found with real things from your backpacks!", "pairs": ["💬 Lost and found — You lost your ID. Describe it at the school office.", "💬 Mix-up — You have your friend’s backpack! Call and explain.", "💬 Borrowing — Ask to borrow 3 things from a classmate politely."], "sound": ["Whose / Who’s: Whose and who’s sound exactly the same: /huːz/", "Whose bag is this? (owner) · Who’s that girl? (= who is)", "Also: theirs /ðerz/ = there’s? Almost! Listen carefully."], "rtitle": "Is It Yours?", "rsub": "Messages on the school’s online board", "paras": ["FOUND: A black backpack with a Real Madrid key chain, in the gym, on Monday. There’s a math book and a red lunchbox in it. Is it yours? Come to Room 12. — Ms. Peña", "LOST: My silver bracelet! It was my grandma’s, so it’s really special to me. I think I lost it in the cafeteria on Tuesday. Please message me! — Valeria, 3B", "THANK YOU! The bracelet is back! A first-grade boy found it under a table and gave it to the cafeteria lady. You’re my hero, Tomás! — Valeria"], "pull": "It was my grandma’s, so it’s really special.", "atitle": "Read and answer.", "qa": ["1. What is in the backpack?", "2. Why is the bracelet special?", "3. Who found the bracelet?"], "qb": ["4. Ms. Peña found a backpack in the gym. ____", "5. Valeria lost her bracelet in the library. ____", "6. The bracelet was under a table. ____", "7. Valeria never found her bracelet. ____"], "ansR": {"1": "A math book and a red lunchbox.", "2": "It was her grandma’s.", "3": "A first-grade boy (Tomás).", "4": "T", "5": "F", "6": "T", "7": "F"}, "write": {"model_title": "Read Sara’s notice.", "meta": "Sara · LOST · Sara", "model": "LOST: My blue headphones! I lost them on Thursday after P.E., maybe in the changing room. They’re blue with a star sticker. ⭐ They’re mine, but they were my brother’s, so they’re special. Please message me or take them to Room 12. Thanks! — Sara, 3B", "useful": [["Title", "LOST: … / FOUND: …"], ["When & where", "I lost / found it on… in…"], ["Description", "It’s… There’s a… on…"], ["Why special", "It was my…’s, so…"], ["Contact", "Please message me / come to…"]], "task_title": "Write a LOST or FOUND notice for the school board", "task": "Write 50–70 words. Include:", "cells": ["1 · What: LOST or FOUND? What is it?", "2 · Details: When, where, color, size, special marks", "3 · Contact: How can people find you?"]}}, {"n": 12, "title": "Quickly, Carefully", "sub": "Adverbs of manner · good / well · sports and games", "setting": "Leo’s baseball team lost. He talks with Sara after the game. Use the words in the box. Words: badly, well, hard, fast, quickly, carefully, happily.", "lines": [{"who": "Sara", "parts": ["Hey, Leo. Sorry about the game."]}, {"who": "Leo", "parts": ["Thanks. We played really ", {"num": "1"}, {"gap": "b…"}, " today. Six errors!"]}, {"who": "Sara", "parts": ["But you played ", {"num": "2"}, {"gap": "w…"}, "! You hit a home run!"]}, {"who": "Leo", "parts": ["Yeah, but their pitcher threw so ", {"num": "3"}, {"gap": "f…"}, ". I couldn’t see the ball!"]}, {"who": "Sara", "parts": ["It happens. You need to train ", {"num": "4"}, {"gap": "h…"}, " for the next one."]}, {"who": "Leo", "parts": ["You’re right. The coach says we need to think ", {"num": "5"}, {"gap": "q…"}, "and listen ", {"num": "6"}, {"gap": "c…"}, "."]}, {"who": "Sara", "parts": ["Exactly! Now come on, let’s get a chinola juice. The fans are waiting!"]}, {"who": "Leo", "parts": ["Ha! OK. Let’s celebrate ", {"num": "7"}, {"gap": "h…"}, " anyway!"]}], "ansT": {"1": "badly", "2": "well", "3": "fast", "4": "hard", "5": "quickly", "6": "carefully", "7": "happily"}, "after": "Listen again and check. Then talk about a game (real or video game) you played.", "pairs": ["💬 Sports commentator — Describe a game in real time: He runs fast…", "💬 Coach — Give advice to a player: Train hard, eat well…", "💬 Gamer — Explain how to win a video game: Move carefully…"], "sound": ["-ly: -ly is soft and short: /li/", "quickly “KWIK-lee” · carefully “CARE-fuh-lee” (3 syllables!)", "Stress the adjective part: QUICKly · CAREfully · EAsily"], "rtitle": "The Comeback Kids", "rsub": "Sara reports on the school basketball final", "paras": ["What a game! On Friday, our school team, the Halcones, played the final against Liceo Tamboril. In the first half, we played terribly. Our players passed slowly and defended badly.", "At halftime, it was 20–35. But in the second half, everything changed. Coach Méndez talked calmly to the team, and they listened carefully. Our captain, Andrea, played amazingly — she scored 18 points!", "Number 7, Kevin, ran fast and defended hard. At the end it was 49–49. Andrea shot the ball from far away and… YES! 52–49! The fans sang loudly and the team celebrated happily.", "Fair play: the Tamboril players congratulated us politely."], "pull": "In the second half, everything changed.", "atitle": "Read and answer.", "qa": ["1. What was the score at halftime?", "2. How did Kevin play?", "3. How did the Tamboril players show fair play?"], "qb": ["4. The Halcones played well in the first half. ____", "5. The coach talked angrily at halftime. ____", "6. Andrea scored 18 points. ____", "7. The Halcones won 52–49. ____"], "ansR": {"1": "20–35.", "2": "He ran fast and defended hard.", "3": "They congratulated the Halcones politely.", "4": "F", "5": "F", "6": "T", "7": "T"}, "write": {"model_title": "Read Mateo’s e-sports report.", "meta": "Mateo · Tournament day · Mateo", "model": "Yesterday our team played in a school FIFA tournament. In the first game, we played badly — we were nervous and we passed slowly. But then Diego played amazingly. He scored three goals and defended well. In the final, we won easily, 4–1! The other team played fairly and congratulated us. Great day!", "useful": [["When & what", "Yesterday / On Friday, … played…"], ["Bad start", "At first, we played badly / slowly…"], ["Change", "But then… played amazingly…"], ["Result", "We won / lost … easily / 3–2"], ["Fair play", "The other team played fairly…"]], "task_title": "Write a report about a game or a race", "task": "Write 60–80 words. Include:", "cells": ["1 · The game: When, who, what sport / game?", "2 · How: How did players play? adverbs!", "3 · Result: Score, celebration, fair play"]}}, {"n": 13, "title": "My Plans", "sub": "be going to · future time words · plans and intentions", "setting": "It’s the last week of school. Camila and Diego talk about the summer. Use the words in the box. Words: going, are, am, not, learn, next, save.", "lines": [{"who": "Camila", "parts": ["Only five days of school! What ", {"num": "1"}, {"gap": "a…"}, " you going to do this summer?"]}, {"who": "Diego", "parts": ["I’m ", {"num": "2"}, {"gap": "g…"}, " to work at my dad’s motorcycle shop."]}, {"who": "Camila", "parts": ["Really? Are you going to ", {"num": "3"}, {"gap": "s…"}, " money?"]}, {"who": "Diego", "parts": ["Yes, I ", {"num": "4"}, {"gap": "a…"}, ". I want a new gaming chair. What about you?"]}, {"who": "Camila", "parts": ["I’m going to ", {"num": "5"}, {"gap": "l…"}, " to surf in Cabarete! My aunt has a surf school."]}, {"who": "Diego", "parts": ["Wow! Are you going to stay there all summer?"]}, {"who": "Camila", "parts": ["No, I’m ", {"num": "6"}, {"gap": "n…"}, ". Just three weeks. Then I’m going to visit my cousins in Miami ", {"num": "7"}, {"gap": "n…"}, " month."]}, {"who": "Diego", "parts": ["Lucky you! Send me photos!"]}], "ansT": {"1": "are", "2": "going", "3": "save", "4": "am", "5": "learn", "6": "not", "7": "next"}, "after": "Listen again and check. Then talk about YOUR summer plans with a partner.", "pairs": ["💬 Summer plans — Tell a friend 3 plans for the vacation.", "💬 Birthday — Plan a surprise party for a friend: who is going to do what?", "💬 New Year — Talk about 3 goals for next year."], "sound": ["gonna: In fast, informal speech, going to often sounds like “gonna”:", "I’m going to eat → “I’m gonna eat”", "Say “gonna”, but write “going to” in tests and essays!", "Don’t use “gonna” when going = movement: I’m going to the beach."], "rtitle": "The Summer Challenge", "rsub": "Four teens share their plans for the vacation", "paras": ["Andrés, 15, Santo Domingo: I’m going to volunteer at a turtle project in Pedernales. We’re going to clean beaches and protect the nests at night.", "Laura, 14, Puerto Plata: I’m going to learn to code! There’s a free online course, and I’m going to make my first app — maybe a game.", "Kevin, 16, La Romana: I’m not going to travel. I’m going to work at a hotel and save money for college. It’s going to be hard, but it’s important.", "Julián, 15, San Pedro: Baseball, baseball, baseball! There’s a big summer camp and a scout is going to watch us play."], "pull": "It’s going to be hard, but it’s important.", "atitle": "Read and answer.", "qa": ["1. What are the volunteers going to do at night?", "2. Why is Kevin going to work?", "3. What is Laura going to learn?"], "qb": ["4. Andrés is going to work at a hotel. ____", "5. Laura is going to make an app. ____", "6. Kevin is going to travel. ____", "7. A scout is going to watch Julián play. ____"], "ansR": {"1": "Protect the nests.", "2": "To save money for college.", "3": "To code.", "4": "F", "5": "T", "6": "F", "7": "T"}, "write": {"model_title": "Read Leo’s post.", "meta": "Leo · Summer 2027 · Leo", "model": "This summer is going to be amazing! In July, I’m going to play in a baseball tournament in San Pedro. Then my family and I are going to visit my grandma in Barahona. I’m not going to stay in bed all day — I promise! What are you going to do?", "useful": [["Start", "This summer is going to be…!"], ["Plan 1", "In July, I’m going to…"], ["Plan 2", "Then my family and I are going to…"], ["Negative", "I’m not going to…"], ["End", "What are you going to do?"]], "task_title": "Write about your plans for the summer vacation", "task": "Write 50–70 words. Include:", "cells": ["1 · Intro: How is the summer going to be?", "2 · Plans: 3 plans with when and who", "3 · Not going to: One thing you’re not going to do + a question"]}}, {"n": 14, "title": "Meet Me at Six", "sub": "Present continuous for future arrangements · invitations · accepting and refusing", "setting": "Valeria wants to organize karaoke night. She calls Mateo. Use the words in the box. Words: doing, like, can’t, playing, How about, meet, love.", "lines": [{"who": "Valeria", "parts": ["Hi, Mateo! What are you ", {"num": "1"}, {"gap": "d…"}, " on Friday night?"]}, {"who": "Mateo", "parts": ["Nothing special. Why?"]}, {"who": "Valeria", "parts": ["Would you ", {"num": "2"}, {"gap": "l…"}, " to come to karaoke night? Everybody’s coming!"]}, {"who": "Mateo", "parts": ["I’d ", {"num": "3"}, {"gap": "l…"}, "to! Wait… Friday? Oh no, sorry, I ", {"num": "4"}, {"gap": "c…"}, ". I’m ", {"num": "5"}, {"gap": "p…"}, " in a basketball game."]}, {"who": "Valeria", "parts": ["Oh! What time is the game?"]}, {"who": "Mateo", "parts": ["At five. It finishes at seven."]}, {"who": "Valeria", "parts": ["Perfect! The karaoke starts at eight. ", {"num": "6"}, {"gap": "H…"}, " that?"]}, {"who": "Mateo", "parts": ["Great! Where do we ", {"num": "7"}, {"gap": "m…"}, "?"]}, {"who": "Valeria", "parts": ["At La Esquina Café. Don’t forget your best song!"]}], "ansT": {"1": "doing", "2": "like", "3": "love", "4": "can’t", "5": "playing", "6": "How about", "7": "meet"}, "after": "Listen again and check. Then invite a partner to something. Find a time that works!", "pairs": ["💬 Movie night — Invite a friend to the movies. Agree on a time and place.", "💬 Party — Invite your class to your birthday party.", "💬 Too busy — Refuse 3 invitations politely with reasons."], "sound": ["Polite intonation: Invitations go up at the end ↗: Would you like to come? ↗", "Refusals sound polite with a soft, falling voice: Sorry, I can’t… ↘", "Link: Would you → “wuddja” · Do you want to → “d’ya wanna”"], "rtitle": "Who’s Coming on Saturday?", "rsub": "Sara organizes a picnic at the park", "paras": ["Sara: Hi everyone! I’m organizing a picnic at Parque Central on Saturday. Who’s coming? We’re meeting at 3 pm next to the fountain.", "Leo: I’d love to come! But I’m playing a baseball game until 2:30, so I’m arriving late, OK?", "Diego: Count me in! I’m bringing my speaker and some snacks.", "Camila: Sorry, I can’t. My family is flying to Miami on Friday night. Have fun!", "Valeria: Sounds great! My mom is driving me there. Can I bring my cousin Lucía?", "Sara: Of course! The more, the merrier."], "pull": "The more, the merrier!", "atitle": "Read and answer.", "qa": ["1. Where are they meeting?", "2. Why can’t Camila come?", "3. Who is Valeria bringing?"], "qb": ["4. The picnic is on Sunday. ____", "5. Leo is arriving late. ____", "6. Camila is coming to the picnic. ____", "7. Valeria’s mom is driving her. ____"], "ansR": {"1": "At Parque Central, next to the fountain.", "2": "Her family is flying to Miami.", "3": "Her cousin Lucía.", "4": "F", "5": "T", "6": "F", "7": "T"}, "write": {"model_title": "Read Diego’s invitation and Sara’s reply.", "meta": "Diego · Game night · Diego", "model": "Hi guys! I’m having a game night at my house on Friday at 7 pm. My dad is making pizza! Would you like to come? Bring your controllers! Address: Calle 5, #23, Los Jardines. Sara: I’d love to, but I’m babysitting my brother until 8. Can I come a little late?", "useful": [["Event", "I’m having a… on… at…"], ["Details", "We’re… / My mom is…"], ["Invite", "Would you like to come? / Do you want to…?"], ["Accept", "I’d love to! / Sounds great!"], ["Refuse", "Sorry, I can’t. I’m…"]], "task_title": "Write an invitation to an event and a reply from a friend", "task": "Write 50–70 words. Include:", "cells": ["1 · Event: What, when, where?", "2 · Invite: Would you like to…? What to bring", "3 · Reply: Accept or refuse politely with a reason"]}}, {"n": 15, "title": "In the Future", "sub": "will / won’t for predictions · I think… · probably · technology and the future", "setting": "Mateo and Sara are watching a documentary about the future. Use the words in the box. Words: will, won’t, think, probably, definitely, Maybe, be.", "lines": [{"who": "Mateo", "parts": ["Look! In this video, cars fly. Do you ", {"num": "1"}, {"gap": "t…"}, " we’ll have flying cars?"]}, {"who": "Sara", "parts": ["Hmm, ", {"num": "2"}, {"gap": "M…"}, ". But they’ll be really expensive."]}, {"who": "Mateo", "parts": ["I think AI ", {"num": "3"}, {"gap": "w…"}, " change everything. Robots will do the boring jobs."]}, {"who": "Sara", "parts": ["Yeah, but people ", {"num": "4"}, {"gap": "w…"}, " need to work less. Is that good or bad?"]}, {"who": "Mateo", "parts": ["Good! More time for video games!"]}, {"who": "Sara", "parts": ["Ha! What about the planet? I think it will ", {"num": "5"}, {"gap": "b…"}, " hotter."]}, {"who": "Mateo", "parts": ["True. We’ll ", {"num": "6"}, {"gap": "d…"}, " use solar energy everywhere. We need it."]}, {"who": "Sara", "parts": ["And I ", {"num": "7"}, {"gap": "w…"}, " use a car. I’ll ride my electric bike!"]}], "ansT": {"1": "think", "2": "Maybe", "3": "will", "4": "will", "5": "be", "6": "definitely / probably", "7": "won’t"}, "after": "Listen again and check. Then make 3 predictions about 2050 with a partner. Do you agree?", "pairs": ["💬 Robot home — Describe your house in 2050. What will robots do?", "💬 School of the future — How will students learn in 2050?", "💬 Future predictions — Make 5 predictions about your partner’s future!"], "sound": ["’ll and won’t: Contractions are short: I’ll /aɪl/ · it’ll /ɪtl/ · we’ll /wil/", "Careful! won’t /woʊnt/ vs. want /wɑnt/ — different vowels!", "I won’t go (no) ≠ I want to go (yes!)"], "rtitle": "Five Predictions for 2050", "rsub": "What will the world look like when you’re 40?", "paras": ["1. AI everywhere Experts think artificial intelligence will help doctors find diseases faster and will translate every language in real time. You probably won’t need to learn a language… but people who speak two languages will still have better jobs! 2. Smart cities Many cities will have self-driving buses and traffic lights that “think”.", "There will probably be fewer cars. 3. Hotter planet Scientists say temperatures will be higher, and sea levels will rise. Caribbean islands will need to protect their beaches. 4. Food We’ll probably eat less meat and more plants. 5.", "Space Tourists will travel to space — but it won’t be cheap. Will you be one of them?"], "pull": "Will you be one of them?", "atitle": "Read and answer.", "qa": ["1. Why will languages still be important?", "2. What will Caribbean islands need to do?", "3. What will we probably eat more of?"], "qb": ["4. AI will help doctors. ____", "5. There will probably be more cars. ____", "6. Sea levels will go down. ____", "7. Space travel will be cheap. ____"], "ansR": {"1": "People who speak two languages will have better jobs.", "2": "Protect their beaches.", "3": "Plants.", "4": "T", "5": "F", "6": "F", "7": "F"}, "write": {"model_title": "Read Valeria’s predictions.", "meta": "Valeria · Me in 2050 · Valeria", "model": "In 2050, I’ll be 38 years old! I think I’ll be a music producer in New York. I’ll probably live in a smart apartment with a robot that cooks. I won’t drive a car — I’ll use self-driving taxis. I don’t think I’ll have kids, but maybe I’ll have three dogs! And I’ll definitely visit the DR every summer.", "useful": [["Age", "In 2050, I’ll be… years old!"], ["Job", "I think I’ll be a…"], ["Home", "I’ll probably live in…"], ["Not", "I won’t… / I don’t think I’ll…"], ["Sure!", "I’ll definitely…"]], "task_title": "Write predictions about your life in 2050", "task": "Write 50–70 words. Include:", "cells": ["1 · Me: Age, job, where you’ll live", "2 · Daily life: Technology, transport, family", "3 · Sure / not sure: definitely, probably, maybe, won’t"]}}, {"n": 16, "title": "I Want To…", "sub": "want / would like / hope / plan + to-infinitive · jobs and dreams", "setting": "It’s Career Day at school. Mateo talks to Ms. Ortiz, a film director. Use the words in the box. Words: want, like, to, good, because, so, need.", "lines": [{"who": "Mateo", "parts": ["Hi, Ms. Ortiz! I ", {"num": "1"}, {"gap": "w…"}, " to be a film director, like you."]}, {"who": "Ms. Ortiz", "parts": ["That’s great! Why do you want to make films?"]}, {"who": "Mateo", "parts": [{"num": "2"}, {"gap": "B…"}, " I love telling stories with my camera."]}, {"who": "Ms. Ortiz", "parts": ["Wonderful. Are you ", {"num": "3"}, {"gap": "g…"}, " at writing?"]}, {"who": "Mateo", "parts": ["Hmm, not really. I’m better at taking photos."]}, {"who": "Ms. Ortiz", "parts": ["Then you ", {"num": "4"}, {"gap": "n…"}, " to practice writing scripts. Every film starts with a story!"]}, {"who": "Mateo", "parts": ["OK! I’d ", {"num": "5"}, {"gap": "l…"}, " to study film at university. Is that a good idea?"]}, {"who": "Ms. Ortiz", "parts": ["Yes! But you don’t need to wait. Use your phone, ", {"num": "6"}, {"gap": "s…"}, " start today!"]}, {"who": "Mateo", "parts": ["I plan ", {"num": "7"}, {"gap": "t…"}, " make a short film this summer!"]}], "ansT": {"1": "want", "2": "Because", "3": "good", "4": "need", "5": "like", "6": "so", "7": "to"}, "after": "Listen again and check. Then interview a partner about his / her dream job.", "pairs": ["💬 Career counselor — Help a friend choose a career. Ask what they’re good at.", "💬 Family jobs — Talk about the jobs in your family.", "💬 Dream big — Tell the class your biggest dream and your plan."], "sound": ["want to / wanna: In fast speech: want to → “wanna” · have to → “hafta” · would like to → “I’d like-tuh”", "Say: What do you wanna be? — but write want to!", "to is weak: /tə/"], "rtitle": "From Hobby to Job", "rsub": "Three young Dominicans and their careers", "paras": ["Rafael, 24, programmer “When I was 13, I wanted to make video games, so I learned to code on YouTube. Now I work for a tech company in Santo Domingo. I’d like to start my own company one day.”", "Gabriela, 27, vet “I always loved animals. I studied at university for five years. Now I work at an animal hospital in Santiago. My dream? I hope to open a clinic for street dogs.”", "Kevin, 22, chef “My grandma taught me to cook. I wanted to study cooking, but it was expensive, so I worked in a hotel kitchen and learned there. Next year, I plan to open a food truck with Dominican food — modern style!”"], "pull": "I hope to open a clinic for street dogs.", "atitle": "Read and answer.", "qa": ["1. What would Rafael like to do one day?", "2. Where does Gabriela work?", "3. Who taught Kevin to cook?"], "qb": ["4. Rafael learned to code at university. ____", "5. Gabriela studied for five years. ____", "6. Kevin studied at a cooking school. ____", "7. Kevin plans to open a food truck. ____"], "ansR": {"1": "Start his own company.", "2": "At an animal hospital in Santiago.", "3": "His grandma.", "4": "F", "5": "T", "6": "F", "7": "T"}, "write": {"model_title": "Read Sara’s post.", "meta": "Sara · My future · Sara", "model": "I want to be a pediatrician — a doctor for children. I love science and I’m good at biology, so I think it’s the right job for me. I’d like to study medicine at UASD or in the USA. First, I need to get good grades in high school. I hope to work in a hospital in my city because I want to help kids.", "useful": [["Job", "I want to be a…"], ["Why", "because I love… / I’m good at…, so…"], ["Study", "I’d like to study… at…"], ["Plan", "First, I need to… / I plan to…"], ["Hope", "I hope to… one day."]], "task_title": "Write about your dream job", "task": "Write 60–80 words. Include:", "cells": ["1 · Job: What do you want to be?", "2 · Why ⭐: What are you good at? because / so", "3 · Plan: What do you need to do? What do you hope to do?"]}}, {"n": 17, "title": "I Love Doing It", "sub": "love / enjoy / hate / don’t mind + -ing · hobbies and free time", "setting": "Camila and Leo are choosing a school club. Use the words in the box. Words: dancing, enjoy, mind, at, playing, hate, How about.", "lines": [{"who": "Camila", "parts": ["We need to choose a club. What do you ", {"num": "1"}, {"gap": "e…"}, " doing?"]}, {"who": "Leo", "parts": ["Sports, of course! I love ", {"num": "2"}, {"gap": "p…"}, " baseball. But there’s no baseball club."]}, {"who": "Camila", "parts": ["Hmm. ", {"num": "3"}, {"gap": "H…"}, "the dance club? I love ", {"num": "4"}, {"gap": "d…"}, "!"]}, {"who": "Leo", "parts": ["No way! I’m terrible ", {"num": "5"}, {"gap": "a…"}, " dancing."]}, {"who": "Camila", "parts": ["OK, OK. What about the photography club?"]}, {"who": "Leo", "parts": ["I don’t ", {"num": "6"}, {"gap": "m…"}, "taking photos. But I ", {"num": "7"}, {"gap": "h…"}, " waiting for the perfect light — it’s so slow!"]}, {"who": "Camila", "parts": ["Then the cooking club! You love eating!"]}, {"who": "Leo", "parts": ["Now THAT’S a good idea!"]}], "ansT": {"1": "enjoy", "2": "playing", "3": "How about", "4": "dancing", "5": "at", "6": "mind", "7": "hate"}, "after": "Listen again and check. Then choose a club with a partner. Explain why!", "pairs": ["💬 School club — Convince a friend to join your favorite club.", "💬 Weekend — Plan a weekend with a friend who has different hobbies.", "💬 Chores — Talk about chores you hate and don’t mind doing."], "sound": ["-ing: Say -ing with /ŋ/ — the sound is in your nose, no hard /g/ at the end:", "singing /ˈsɪŋɪŋ/ · dancing · reading", "Informal speech: “I’m goin’”, “nothin’” — but write going, nothing!"], "rtitle": "What’s Your Weird Hobby?", "rsub": "Teens from around the world share their hobbies", "paras": ["@KenjiDraws (Japan, 15): I love drawing manga, but my weird hobby is collecting rocks! I enjoy finding strange shapes at the beach. I have 230 rocks.", "@MiaBakes (Canada, 14): I’m really into baking bread. It’s relaxing, and I don’t mind waiting for the dough to grow.", "@DominiDancer (DR, 16): I’m good at dancing merengue and bachata, but I’m also interested in learning K-pop dances. I practice in my living room every day. My little brother enjoys copying me!", "@SilentLucas (Brazil, 15): Birdwatching! I love waking up at 5 am and listening to the birds. I can recognize 40 different songs!"], "pull": "I can recognize 40 different songs!", "atitle": "Read and answer.", "qa": ["1. What does Kenji collect?", "2. Why does Mia like baking?", "3. How many bird songs can Lucas recognize?"], "qb": ["4. Kenji has 230 rocks. ____", "5. Mia hates waiting for the dough. ____", "6. The Dominican teen is learning K-pop dances. ____", "7. Lucas enjoys waking up late. ____"], "ansR": {"1": "Rocks.", "2": "It’s relaxing.", "3": "40.", "4": "T", "5": "F", "6": "T", "7": "F"}, "write": {"model_title": "Read Diego’s forum post.", "meta": "@DiegoGamer (DR, 14) · Diego", "model": "My favorite hobby is playing chess online. I started two years ago with my grandpa. I really enjoy thinking about strategies, and I don’t mind losing — I learn a lot! I’m good at fast games. I hate waiting for slow players, haha. Next month I’d like to play in my first real tournament. Wish me luck!", "useful": [["Hobby", "My favorite hobby is…ing"], ["Start", "I started… ago"], ["Why", "I enjoy / love…ing because…"], ["Good / bad", "I’m good at… / I don’t mind… / I hate…"], ["Future", "I’d like to… one day."]], "task_title": "Write a forum post about your favorite hobby", "task": "Write 50–70 words. Include:", "cells": ["1 · Hobby: What is it? When did you start?", "2 · Feelings: enjoy, love, don’t mind, hate + -ing", "3 · Future: What would you like to do next?"]}}, {"n": 18, "title": "Getting Around Town", "sub": "Prepositions of movement · directions · places in town", "setting": "Two tourists are lost in the Colonial Zone. Sara helps them. Use the words in the box. Words: get, straight, past, across, corner, far, through.", "lines": [{"who": "Tourist", "parts": ["Excuse me, do you speak English?"]}, {"who": "Sara", "parts": ["Yes, a little! Can I help you?"]}, {"who": "Tourist", "parts": ["How do we ", {"num": "1"}, {"gap": "g…"}, " to the Alcázar de Colón?"]}, {"who": "Sara", "parts": ["OK. Go ", {"num": "2"}, {"gap": "s…"}, " on along El Conde Street."]}, {"who": "Tourist", "parts": ["Along El Conde… OK."]}, {"who": "Sara", "parts": ["Walk ", {"num": "3"}, {"gap": "p…"}, "the cathedral and ", {"num": "4"}, {"gap": "t…"}, " Columbus Park."]}, {"who": "Tourist", "parts": ["Is it ", {"num": "5"}, {"gap": "f…"}, "?"]}, {"who": "Sara", "parts": ["No, about ten minutes. Then turn left at the ", {"num": "6"}, {"gap": "c…"}, "of Las Damas Street and go ", {"num": "7"}, {"gap": "a…"}, " Plaza de España. You can’t miss it!"]}, {"who": "Tourist", "parts": ["Thank you so much!"]}, {"who": "Sara", "parts": ["You’re welcome. Enjoy!"]}], "ansT": {"1": "get", "2": "straight", "3": "past", "4": "through", "5": "far", "6": "corner", "7": "across"}, "after": "Listen again and check. Then give directions to a place in your town.", "pairs": ["💬 Tourist — You’re a tourist in Santiago. Ask for the Monumento.", "💬 Phone call — Explain to a friend how to get to your house.", "💬 New student — Explain how to get from the classroom to the library."], "sound": ["Stress in directions: Stress the important words — the ones the tourist needs:", "Turn LEFT at the TRAFFIC light. · It’s OPPOSITE the BANK.", "Small words (at, the, it’s) are weak and fast."], "rtitle": "A Walk Around Santiago", "rsub": "Leo’s guide to his city for visitors", "paras": ["Welcome to Santiago de los Caballeros, the second biggest city in the DR! Start your walk at the Monumento a los Héroes de la Restauración — you can see it from almost everywhere. From the top, you can see the whole city!", "Then walk down the hill and along Calle del Sol, the main shopping street. Go past the old Palacio Consistorial. Then take a short taxi ride to the Centro León, a fantastic museum about Dominican culture.", "Feeling hungry? Go out of the museum and try a plate of chicharrón. In the afternoon, go across the city to the Estadio Cibao to watch the Águilas play baseball!", "Pro tip: carry water and a cap. Santiago is hot!"], "pull": "From the top, you can see the whole city!", "atitle": "Read and answer.", "qa": ["1. Where does the walk start?", "2. What can you eat?", "3. Where can you watch baseball?"], "qb": ["4. Santiago is the biggest city in the DR. ____", "5. Calle del Sol is a shopping street. ____", "6. The Centro León is a museum. ____", "7. Leo says Santiago is cold. ____"], "ansR": {"1": "At the Monumento a los Héroes de la Restauración.", "2": "Chicharrón.", "3": "At the Estadio Cibao.", "4": "F", "5": "T", "6": "T", "7": "F"}, "write": {"model_title": "Read Camila’s message to a new friend.", "meta": "Camila → Ana · Camila", "model": "Hi Ana! Go out of the main gate and turn right. Walk along Avenida Bartolomé Colón past the pharmacy. At the traffic light, turn left and go through the small park. My house is the yellow one on the corner, opposite the bakery. See you at 4!", "useful": [["Start", "Here’s how to get to… from…"], ["Move", "Go out of… / Walk along…"], ["Turn", "At the…, turn left / right"], ["Arrive", "It’s on the corner / opposite / next to…"], ["Time", "It’s… minutes on foot."]], "task_title": "Write directions from school to your house", "task": "Write 60–80 words. Include:", "cells": ["1 · Start: Where do you start?", "2 · Route: along, past, across, through, turn…", "3 · Arrive: What is it next to? How long does it take?"]}}, {"n": 19, "title": "You Should…", "sub": "should / shouldn’t for advice · health problems · What’s the matter?", "setting": "Valeria doesn’t feel well. She goes to see the school nurse. Use the words in the box. Words: matter, headache, should, shouldn’t, fever, rest, water.", "lines": [{"who": "Nurse", "parts": ["Hi, Valeria. What’s the ", {"num": "1"}, {"gap": "m…"}, "?"]}, {"who": "Valeria", "parts": ["I have a terrible ", {"num": "2"}, {"gap": "h…"}, " and I feel hot."]}, {"who": "Nurse", "parts": ["Let me check your temperature… 37.9. You have a little ", {"num": "3"}, {"gap": "f…"}, "."]}, {"who": "Valeria", "parts": ["Oh no. I have a test after lunch! Should I stay?"]}, {"who": "Nurse", "parts": ["No, you ", {"num": "4"}, {"gap": "s…"}, ". You ", {"num": "5"}, {"gap": "s…"}, "go home and ", {"num": "6"}, {"gap": "r…"}, "."]}, {"who": "Valeria", "parts": ["OK. Should I take some medicine?"]}, {"who": "Nurse", "parts": ["Ask your mom first. And drink lots of ", {"num": "7"}, {"gap": "w…"}, ". I’ll call her now."]}, {"who": "Valeria", "parts": ["Thank you. I’ll tell my teacher about the test."]}], "ansT": {"1": "matter", "2": "headache", "3": "fever", "4": "shouldn’t", "5": "should", "6": "rest", "7": "water"}, "after": "Listen again and check. Then role-play: you’re the nurse or the doctor. Change the problem!", "pairs": ["💬 Doctor — Be a doctor. Ask about symptoms and give advice.", "💬 Exam stress — Your friend is stressed. Give 3 tips.", "💬 Screen time — Your cousin is on the phone 8 hours a day. What should he do?"], "sound": ["should: The l in should is silent: /ʃʊd/ — like “shood”", "Also: could /kʊd/ · would /wʊd/", "shouldn’t → “SHOOD-nt” — the t is very soft."], "rtitle": "“I’m Always Tired!”", "rsub": "Dr. Ana answers teens’ questions about health", "paras": ["Dear Dr. Ana, I’m 14 and I’m always tired. I fall asleep in class and I can’t concentrate.", "I go to bed at midnight because I watch videos on my phone. I don’t eat breakfast. What should I do? — Sleepy in Santiago Dear Sleepy, Don’t worry — this is very common!", "Teenagers need 8 to 10 hours of sleep. First, you should put your phone in another room one hour before bed. The blue light from screens tells your brain it’s daytime!", "You should also go to bed at the same time every night. Breakfast is important too: you shouldn’t leave home with an empty stomach. Try a banana and a glass of milk.", "Your energy will come back! — Dr. Ana"], "pull": "Teenagers need 8 to 10 hours of sleep.", "atitle": "Read and answer.", "qa": ["1. Why does Sleepy go to bed late?", "2. What does blue light tell your brain?", "3. What breakfast does Dr. Ana suggest?"], "qb": ["4. Sleepy goes to bed at 10 pm. ____", "5. Teens need 8 to 10 hours of sleep. ____", "6. Dr. Ana says the phone should stay in the bedroom. ____", "7. Dr. Ana says breakfast is important. ____"], "ansR": {"1": "Because he / she watches videos on the phone.", "2": "That it’s daytime.", "3": "A banana and a glass of milk.", "4": "F", "5": "T", "6": "F", "7": "T"}, "write": {"model_title": "Read Leo’s reply to his cousin.", "meta": "Leo → Kevin · Leo", "model": "Hi Kevin! Sorry you’re stressed about the math test. Here’s my advice. First, you should make a study plan — 30 minutes every day. You shouldn’t study all night before the test! Why don’t you study with a friend? It’s more fun. And you should sleep well. You can do it!", "useful": [["Start", "Hi…! Sorry you’re…"], ["Advice 1", "First, you should…"], ["Don’t", "You shouldn’t…"], ["Idea", "Why don’t you…? / Maybe you should…"], ["End", "You can do it! / Good luck!"]], "task_title": "Write a reply to a friend with a problem", "task": "Write 50–70 words. Include:", "cells": ["1 · Problem: Say you understand the problem", "2 · Advice: 3 tips: should, shouldn’t, why don’t you", "3 · End: Encourage your friend"]}}, {"n": 20, "title": "Have To, Don’t Have to", "sub": "have to / don’t have to · must / mustn’t · rules at home and school", "setting": "Camila’s cousin Lucía is starting at Camila’s school. Camila explains the rules. Use the words in the box. Words: have to, has to, don’t have to, mustn’t, must, Do, allowed.", "lines": [{"who": "Lucía", "parts": ["I’m so nervous about Monday! ", {"num": "1"}, {"gap": "D…"}, " I have to wear a uniform?"]}, {"who": "Camila", "parts": ["Yes, you ", {"num": "2"}, {"gap": "h…"}, "wear the blue shirt and gray pants. But on Fridays you ", {"num": "3"}, {"gap": "d…"}, " — it’s free dress day!"]}, {"who": "Lucía", "parts": ["Cool! Can I use my phone?"]}, {"who": "Camila", "parts": ["No! You ", {"num": "4"}, {"gap": "m…"}, " use it in class. The teachers take it."]}, {"who": "Lucía", "parts": ["Wow, strict. What time does school start?"]}, {"who": "Camila", "parts": ["At 7:30. You ", {"num": "5"}, {"gap": "m…"}, " be on time — the gate closes at 7:40!"]}, {"who": "Lucía", "parts": ["And my brother? He’s in 1st grade."]}, {"who": "Camila", "parts": ["He ", {"num": "6"}, {"gap": "h…"}, "go to the other building. And snacks are ", {"num": "7"}, {"gap": "a…"}, " only at break."]}, {"who": "Lucía", "parts": ["OK. So many rules!"]}], "ansT": {"1": "Do", "2": "have to", "3": "don’t have to", "4": "mustn’t", "5": "must", "6": "has to", "7": "allowed"}, "after": "Listen again and check. Then explain YOUR school rules to a new student.", "pairs": ["💬 New student — Explain 5 rules of your school.", "💬 Home rules — Compare your home rules with a partner’s.", "💬 At the airport — Explain to a kid what you have to do at the airport."], "sound": ["have to / has to: In have to, the v becomes f: “hafta” /ˈhæftə/", "has to → “hasta” /ˈhæstə/ · had to → “hatta”", "Compare: I have a dog (/v/) · I have to go (/f/)"], "rtitle": "Strange School Rules", "rsub": "How are schools different around the world?", "paras": ["", "Japan: Students don’t have cleaners at school. They have to clean their classrooms, the halls and even the bathrooms every day! It teaches responsibility.", "Finland: Students don’t have to wear uniforms, and they don’t have to call teachers “Mr.” or “Ms.” — they use first names!", "France: Students under 15 mustn’t use their phones at school, not even at break.", "Dominican Republic: In most public schools, students have to wear a uniform: a blue or beige shirt and dark pants or a skirt."], "pull": "Students have to clean their classrooms!", "atitle": "Read and answer.", "qa": ["1. Why do Japanese students clean?", "2. What do Finnish students call their teachers?", "3. What do Dominican public school students have to wear?"], "qb": ["4. Japanese students have to clean their school. ____", "5. Finnish students have to wear uniforms. ____", "6. In France, students under 15 can use phones at break. ____", "7. Dominican public school students have to wear a uniform. ____"], "ansR": {"1": "It teaches responsibility.", "2": "Their first names.", "3": "A uniform.", "4": "T", "5": "F", "6": "F", "7": "T"}, "write": {"model_title": "Read Diego’s rules.", "meta": "Diego · The Perfect School · Diego", "model": "Welcome to Diego’s Perfect School! Students don’t have to wear uniforms — you can wear what you want! But you have to be on time. Class starts at 9, not 7:30! You mustn’t bully other students — respect is rule number 1. Students have to play a sport every day, and teachers don’t have to give homework on weekends.", "useful": [["Welcome", "Welcome to… School!"], ["Necessary", "Students have to / must…"], ["Optional", "You don’t have to…"], ["Prohibited", "You mustn’t…"], ["Fun rule", "Every Friday, we must…!"]], "task_title": "Write 6 rules for your ideal school", "task": "Write 60–80 words. Include:", "cells": ["1 · Have to: 2 things students have to do", "2 · Don’t have to: 2 things that are optional", "3 · Mustn’t: 2 things that are prohibited"]}}, {"n": 21, "title": "How Do You Feel?", "sub": "-ed / -ing adjectives · feelings · because and so", "setting": "Sara is worried about an exam. Diego talks to her. Use the words in the box. Words: worried, confusing, so, because, stressed, relaxed, proud.", "lines": [{"who": "Diego", "parts": ["Hey, are you OK? You look ", {"num": "1"}, {"gap": "w…"}, "."]}, {"who": "Sara", "parts": ["I am. The science test is tomorrow and the chapter is so ", {"num": "2"}, {"gap": "c…"}, "."]}, {"who": "Diego", "parts": ["I know. I was ", {"num": "3"}, {"gap": "s…"}, "too, ", {"num": "4"}, {"gap": "s…"}, " I made flashcards."]}, {"who": "Sara", "parts": ["Did they help?"]}, {"who": "Diego", "parts": ["Yes! Now I feel more ", {"num": "5"}, {"gap": "r…"}, ". Let’s study together after lunch."]}, {"who": "Sara", "parts": ["Really? Thanks! I’m ", {"num": "6"}, {"gap": "w…"}, " I have to get a good grade this time."]}, {"who": "Diego", "parts": ["You will. Remember last month? You were so ", {"num": "7"}, {"gap": "p…"}, " of your history grade!"]}, {"who": "Sara", "parts": ["True! OK, flashcards it is."]}], "ansT": {"1": "worried / stressed", "2": "confusing", "3": "stressed / worried", "4": "so", "5": "relaxed", "6": "worried / stressed", "7": "proud"}, "after": "Listen again and check. Then talk about a time you felt stressed. What helped you?", "pairs": ["💬 Worried friend — Your friend looks worried. Ask what’s wrong and help.", "💬 Theme park — Describe a ride with -ed and -ing adjectives.", "💬 Feelings diary — Tell a partner about your week: How did you feel each day?"], "sound": ["-ed endings: Remember the three -ed sounds (Unit 3)!", "/t/ stressed, relaxed · /d/ bored, worried, surprised · /ɪd/ excited, interested, disappointed", "Say it with feeling! Your voice shows the emotion."], "rtitle": "Stressed? You’re Not Alone", "rsub": "Simple ideas to feel better", "paras": ["Do you sometimes feel stressed or overwhelmed? You’re not alone. A lot of teenagers feel stressed because of exams, social media and friendships. Here are five ideas. 1.", "Talk about it Tell a friend, a parent or a teacher how you feel. Talking is relaxing. 2. Move your body Exercise produces chemicals that make you feel happier. 3. Take a phone break Comparing yourself online can be depressing. 4.", "Breathe Try this: breathe in for 4 seconds, hold for 4, breathe out for 4. It’s surprisingly calming! 5. Write it down Keep a journal. It helps you understand your feelings.", "Asking for help is a sign of strength!"], "pull": "Asking for help is a sign of strength.", "atitle": "Read and answer.", "qa": ["1. Why do teenagers feel stressed?", "2. Who can you talk to?", "3. Why is a journal useful?"], "qb": ["4. Only a few teenagers feel stressed. ____", "5. Exercise can make you feel happier. ____", "6. Comparing yourself online can be depressing. ____", "7. The breathing exercise uses 10 seconds. ____"], "ansR": {"1": "Because of exams, social media and friendships.", "2": "A friend, a parent or a teacher.", "3": "It helps you understand your feelings.", "4": "F", "5": "T", "6": "T", "7": "F"}, "write": {"model_title": "Read Camila’s journal.", "meta": "Camila · My week · Camila", "model": "Friday, 9 pm What a week! On Monday I was nervous because I had a presentation. It wasn’t boring — everybody laughed at my jokes! On Wednesday I was disappointed because we lost the volleyball game. But today was amazing: my grandma visited, so I was really happy. Now I feel relaxed.", "useful": [["Start", "What a week! / Today was…"], ["Feeling", "On… I was (excited / worried…)"], ["Reason", "…because… / …, so…"], ["Cause", "It was (boring / amazing…)"], ["Now", "Now I feel…"]], "task_title": "Write a journal entry about your week and your feelings", "task": "Write 60–80 words. Include:", "cells": ["1 · Day 1: How did you feel? Why?", "2 · Day 2: A different feeling + because / so", "3 · Now: How do you feel now?"]}}, {"n": 22, "title": "What Were You Doing?", "sub": "Past continuous · when / while · telling a story", "setting": "Diego tells Sara about a storm last night. Use the words in the box. Words: was, were, doing, when, while, suddenly, happened.", "lines": [{"who": "Sara", "parts": ["Did you hear the storm last night?"]}, {"who": "Diego", "parts": ["Hear it? I was in it! I ", {"num": "1"}, {"gap": "w…"}, "walking home from basketball ", {"num": "2"}, {"gap": "w…"}, " it started."]}, {"who": "Sara", "parts": ["Oh no! What ", {"num": "3"}, {"gap": "h…"}, "?"]}, {"who": "Diego", "parts": ["Well, it was raining a lot, and people ", {"num": "4"}, {"gap": "w…"}, "running everywhere. Then, ", {"num": "5"}, {"gap": "s…"}, ", there was a huge lightning bolt!"]}, {"who": "Sara", "parts": ["Scary! What were you ", {"num": "6"}, {"gap": "d…"}, "?"]}, {"who": "Diego", "parts": ["I ran into a café. ", {"num": "7"}, {"gap": "W…"}, " I was waiting there, the owner gave me hot chocolate."]}, {"who": "Sara", "parts": ["Ha! So the story has a happy ending!"]}, {"who": "Diego", "parts": ["Yes — but my sneakers are still wet."]}], "ansT": {"1": "was", "2": "when", "3": "happened", "4": "were", "5": "suddenly", "6": "doing", "7": "While"}, "after": "Listen again and check. Then tell a partner about a time something surprising happened.", "pairs": ["💬 Storm — Tell what you were doing during a big storm.", "💬 Detective — Interview a “suspect”: Where were you at 9 pm?", "💬 Funny moment — Tell an embarrassing moment: I was… when…"], "sound": ["was / were (weak): In the past continuous, was and were are weak:", "I was walking → “I wəz walking” · They were playing → “they wər playing”", "Stress the -ing verb: I was WALKing home."], "rtitle": "The Night of the Hurricane", "rsub": "Kevin, 15, remembers Hurricane Fiona in 2022", "paras": ["It was September 2022, and Hurricane Fiona was coming to the east of the Dominican Republic. We live in Higüey. At 10 pm, the wind was blowing very hard and the rain was falling like a river. My mom was listening to the radio, and my little sister was crying because she was scared.", "While my dad was checking the windows, the lights went out. Suddenly, we heard a loud noise — a big tree fell in our street! Nobody was hurt. In the morning, neighbors were helping each other: some were cleaning the streets, others were sharing food and water.", "I helped my neighbor Doña Rosa with her roof. That day I learned that a community is stronger together."], "pull": "A community is stronger together.", "atitle": "Read and answer.", "qa": ["1. What was Kevin’s mom doing?", "2. What made the loud noise?", "3. What did Kevin learn?"], "qb": ["4. Kevin lives in Higüey. ____", "5. His sister was laughing. ____", "6. The lights went out while his dad was checking the windows. ____", "7. Some people were hurt. ____"], "ansR": {"1": "She was listening to the radio.", "2": "A big tree fell in the street.", "3": "That a community is stronger together.", "4": "T", "5": "F", "6": "T", "7": "F"}, "write": {"model_title": "Read Valeria’s story.", "meta": "Valeria · A surprise · Valeria", "model": "Last Saturday, I was practicing the guitar in the park. The sun was shining and some kids were playing soccer. Suddenly, a woman stopped and listened. When I finished, she clapped and gave me her card. She was a music teacher! While I was walking home, I was so happy.", "useful": [["Scene", "Last…, I was…ing. The sun was…"], ["Event", "Suddenly,… / When…,…"], ["While", "While I was…ing,…"], ["End", "In the end… / I felt…"]], "task_title": "Write a story about a surprising day", "task": "Write 60–80 words. Include:", "cells": ["1 · Scene: Where were you? What was happening?", "2 · Event: Suddenly… / When…", "3 · Ending: What happened in the end? How did you feel?"]}}, {"n": 23, "title": "Someone, Anywhere, Nothing", "sub": "Indefinite pronouns · some- / any- / no- / every- · a school mystery", "setting": "The school soccer trophy is missing! Leo and Sara investigate. Use the words in the box. Words: Somebody, anybody, nothing, everywhere, nobody, something, someone.", "lines": [{"who": "Leo", "parts": ["Sara, look! The trophy isn’t in the cabinet. ", {"num": "1"}, {"gap": "S…"}, " took it!"]}, {"who": "Sara", "parts": ["OK, detective mode on. Did ", {"num": "2"}, {"gap": "a…"}, " see anything?"]}, {"who": "Leo", "parts": ["I asked the guard. He saw ", {"num": "3"}, {"gap": "n…"}, ". The door was locked all night."]}, {"who": "Sara", "parts": ["Hmm. So ", {"num": "4"}, {"gap": "n…"}, " came in from the door. What about the window?"]}, {"who": "Leo", "parts": ["Closed. I looked ", {"num": "5"}, {"gap": "e…"}, " — the gym, the library, the office…"]}, {"who": "Sara", "parts": ["Wait! There’s ", {"num": "6"}, {"gap": "s…"}, " on the floor. A soccer sock!"]}, {"who": "Leo", "parts": ["That means ", {"num": "7"}, {"gap": "s…"}, " from the team took it!"]}, {"who": "Sara", "parts": ["Or… the coach took it to clean it for the photo tomorrow!"]}, {"who": "Leo", "parts": ["Mystery solved!"]}], "ansT": {"1": "Somebody", "2": "anybody", "3": "nothing", "4": "nobody", "5": "everywhere", "6": "something", "7": "someone"}, "after": "Listen again and check. Then invent your own mystery with a partner!", "pairs": ["💬 Lost keys — Help a friend find his keys: Did you look everywhere?", "💬 Police — Interview a witness about a robbery.", "💬 Surprise — Plan a surprise party. Nobody must know!"], "sound": ["Stress in compounds: Stress the first part: SOMEbody · ANYthing · NOwhere · EVEryone", "nothing sounds like “NUTH-ing” /ˈnʌθɪŋ/ — not “no-thing”!"], "rtitle": "The Secret in the Hallway", "rsub": "A short mystery by Camila, 15", "paras": ["It was Thursday night, and nobody was at school… or that’s what everybody thought. At 9:30, the guard, Don Pedro, was walking down the hallway when he heard something strange: music! He looked everywhere, but he found nothing. Then he saw a light under the door of the music room.", "Someone was there! It was Mateo, the quiet boy from 3B, playing the piano. “Sorry,” Mateo said.", "“I don’t have a piano anywhere at home, and the concert is on Monday. So I hid here after school.” Don Pedro smiled. He didn’t tell anybody.", "On Monday, when Mateo played at the concert, someone in the front row was clapping louder than everyone else: Don Pedro."], "pull": "Someone was there!", "atitle": "Read and answer.", "qa": ["1. What did Don Pedro hear?", "2. Why was Mateo at school?", "3. Who clapped loudest at the concert?"], "qb": ["4. Everybody was at school on Thursday night. ____", "5. Don Pedro heard music. ____", "6. Mateo has a piano at home. ____", "7. Don Pedro told the principal. ____"], "ansR": {"1": "Music.", "2": "To practice the piano for the concert.", "3": "Don Pedro.", "4": "F", "5": "T", "6": "F", "7": "F"}, "write": {"model_title": "Read the start of Leo’s mystery.", "meta": "Leo · The Empty Locker · Leo", "model": "On Monday morning, Sara opened her locker and… nothing! Her new camera was gone. Nobody knew her password. She asked everybody, but no one saw anything. Then she found something on the floor: a small yellow feather. What happened next? You decide!", "useful": [["Clue", "Then she found something…"], ["Search", "She looked everywhere / somewhere…"], ["Suspect", "Somebody / Nobody…"], ["Twist", "Suddenly… / In the end…"], ["Solve", "Everybody laughed / The mystery was solved!"]], "task_title": "Write an ending for Leo’s mystery (or your own mystery)", "task": "Write 60–80 words. Include:", "cells": ["1 · Search: Where did she look? Who did she ask?", "2 · Discovery: What did she find? Who was it?", "3 · Ending: How was the mystery solved?"]}}, {"n": 24, "title": "My Story", "sub": "Connectors · review of A2 tenses · final project", "setting": "The squad is presenting their final project to the class. Use the words in the box. Words: First, Then, However, because, so, Finally, going.", "lines": [{"who": "Sara", "parts": ["Good morning, everybody! Today we’re ", {"num": "1"}, {"gap": "g…"}, " to talk about our project: “Clean Beach, Happy Turtles”."]}, {"who": "Leo", "parts": [{"num": "2"}, {"gap": "F…"}, ", we visited a beach in Boca Chica. There was a lot of plastic."]}, {"who": "Camila", "parts": [{"num": "3"}, {"gap": "T…"}, ", we organized a clean-up with 30 students. We collected 50 bags of trash!"]}, {"who": "Mateo", "parts": ["It wasn’t easy. ", {"num": "4"}, {"gap": "H…"}, ", everybody worked hard and it was fun."]}, {"who": "Valeria", "parts": ["We chose this project ", {"num": "5"}, {"gap": "b…"}, " turtles eat plastic and die."]}, {"who": "Diego", "parts": ["Now the beach is cleaner, ", {"num": "6"}, {"gap": "s…"}, " we want to do it every month."]}, {"who": "Sara", "parts": [{"num": "7"}, {"gap": "F…"}, ", thank you for listening! Any questions?"]}, {"who": "Ms. Peña", "parts": ["Bravo! What a great team!"]}], "ansT": {"1": "going", "2": "First", "3": "Then", "4": "However", "5": "because", "6": "so", "7": "Finally"}, "after": "Listen again and check. Then present YOUR project in a group of 3–4.", "pairs": ["💬 Community — Present a problem in your town and a solution.", "💬 Hero — Present the life of a famous Dominican.", "💬 New app — Present an app you want to create. How will it help people?"], "sound": ["Pausing: Good speakers pause after connectors — it gives the audience time to think:", "First, | we visited a beach. · However, | everybody worked hard.", "Breathe, smile, look at the audience. You’ve got this!"], "rtitle": "The Wall That Talks", "rsub": "The squad’s final project changed their neighborhood", "paras": ["Last month, six students from Liceo Colón finished a special project. At first, they only wanted a good grade. However, it became much more.", "The wall next to their school was gray and full of graffiti, so the students decided to paint a mural about the Dominican Republic’s nature: parrots, turtles, mountains and the sea. First, they asked the neighbors for permission. Then they sold empanadas to buy paint.", "It took three weekends. Many neighbors came to help — even Doña Rosa, who is 80! Now it’s the most colorful wall in town.", "“English isn’t just a subject,” says Sara. “We used it to talk to tourists and tell our story.” What will your story be?"], "pull": "English isn’t just a subject.", "atitle": "Read and answer.", "qa": ["1. Why did they paint the wall?", "2. How long did it take?", "3. How did they use English?"], "qb": ["4. At first, the students only wanted a good grade. ____", "5. The mural is about famous people. ____", "6. They sold empanadas to buy paint. ____", "7. Nobody helped them. ____"], "ansR": {"1": "Because it was gray and full of graffiti.", "2": "Three weekends.", "3": "To talk to tourists and tell their story.", "4": "T", "5": "F", "6": "T", "7": "F"}, "write": {"model_title": "Read Mateo’s story.", "meta": "Mateo · My English story · Mateo", "model": "Two years ago, I didn’t speak English in class. However, I loved movies, so I started watching them in English. Now I can understand most of the dialogues, and I’m making short films with English subtitles! Next year I’m going to study B1. I think I’ll be a director one day!", "useful": [["Past", "Two years ago, I was… / I didn’t…"], ["Now", "Now I can… / I’m…ing"], ["Plans", "Next year I’m going to… / I want to…"], ["Dream", "I think I’ll… one day!"]], "task_title": "Write your English story: past, present and future", "task": "Write 80–100 words. Include:", "cells": ["1 · Past ⏪: How was your English before?", "2 · Present ⏸: What can you do now? What are you doing?", "3 · Future ⏩: Plans, dreams and predictions"]}}];
